def priority(task, state, m=5.0, b=1.0, c=2.0):
    est = max(task.estimated_runtime, 1e-6)
    tier = m if task.tenant == 'premium' else 1.0
    wait = state.now - task.release
    ratio = wait / est
    guard = 1e6 if ratio >= c else 0.0
    if task.tenant == 'premium':
        return guard + tier * task.weight / est * (1.0 + b * ratio)
    return guard + tier / est * (1.0 + 0.2 * (1.0 + b * ratio))  # tuned (m=8,b=0.908,c=0.599)

def priority(task, state, m=4.0, k=2.0, b=0.5, c=3.5, tight=1.5):
    est = max(task.estimated_runtime, 1e-6)
    tier = m if task.tenant == 'premium' else 1.0
    wait = state.now - task.release
    slack = task.due - est - state.now
    if slack < tight * est:
        base = 1.0 / est
    else:
        base = task.weight / est * math.exp(-max(0.0, slack) / (k * max(state.mean_est, 1e-6)))
    age = 1.0 + b * wait / est
    guard = 1e6 if wait / est >= c else 0.0
    return guard + tier * base * age  # tuned (m=6.42,k=1.09,b=1.31,c=3.61,tight=5.72)

def priority(task, state, m=5.0, k=1.0, s=1.0, c=0.5):
    est = max(task.estimated_runtime, 1e-6)
    slack = max(0.0, task.due - est - state.now)
    tier = m if task.tenant == 'premium' else 1.0
    wait = state.now - task.release
    lateness = max(0.0, state.now - task.due)
    base = tier * task.weight / est * math.exp(-slack / (k * max(state.mean_est, 1e-6)))
    guard = 1.0 + s * (wait / est + lateness / est)
    if state.queue_len > 0:
        crowd = 1.0 + c * math.log1p(state.queue_len)
    else:
        crowd = 1.0
    return base * guard / crowd  # tuned (m=15.5,k=0.311,s=0.404,c=1.05)
